  FROM (VALUES
    ('8f96d9e7-18ac-5c62-ba5d-3557b44b3d41'::uuid, '91cfcb3f-ff2a-5bb6-a4b7-231408d09159'::uuid, 'Quelle formule de Montaigne résume son projet éducatif ?', 'mcq', '["« Une tête bien faite plutôt que bien pleine »","« Que sais-je ? »","« Connais-toi toi-même »","« Je pense donc je suis »"]'::jsonb, 0, 'Dans « De l’institution des enfants », *Essais*, I, 26.', 1),
    ('50c52573-53af-5260-b974-76266b680c51'::uuid, '91cfcb3f-ff2a-5bb6-a4b7-231408d09159'::uuid, 'Rousseau prône dans « Émile » une éducation dite…', 'mcq', '["Négative","Encyclopédique","Autoritaire","Religieuse"]'::jsonb, 0, 'Elle protège l’enfant des préjugés au lieu de les lui inculquer.', 2),
    ('9881600c-dfd8-5352-b91c-25171b511fae'::uuid, '91cfcb3f-ff2a-5bb6-a4b7-231408d09159'::uuid, 'Les lois Ferry rendent l’école gratuite, laïque et obligatoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'En 1881-1882 : l’instruction devient une condition de la citoyenneté.', 3),
    ('fffbf22e-8d06-55f8-8b51-3094eac41764'::uuid, '91cfcb3f-ff2a-5bb6-a4b7-231408d09159'::uuid, 'Que soutiennent Bourdieu et Passeron dans « Les Héritiers » ?', 'mcq', '["L’école reproduit les inégalités culturelles sous couvert de mérite","L’école abolit les classes sociales","L’école doit être supprimée","L’école est neutre"]'::jsonb, 0, 'Le capital culturel avantage ceux qui le possèdent déjà.', 4),
    ('7d7eef27-8403-5ac2-ac67-c2c1513e66c7'::uuid, '91cfcb3f-ff2a-5bb6-a4b7-231408d09159'::uuid, 'Ivan Illich défendait l’extension de l’institution scolaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Une société sans école* (1971) soutient l’inverse.', 5),
    ('4e6f6519-d0f7-5e2f-ba75-899f6e9ffd24'::uuid, '91cfcb3f-ff2a-5bb6-a4b7-231408d09159'::uuid, 'Que reproche Paulo Freire à l’éducation « bancaire » ?', 'mcq', '["Le maître dépose un savoir que l’élève reçoit passivement","Elle coûte trop cher","Elle est trop pratique","Elle ignore les mathématiques"]'::jsonb, 0, 'Il lui oppose une pédagogie de la conscientisation.', 6),
    ('6ab5aa41-da1d-53da-8e2f-e99ce4304b38'::uuid, '91cfcb3f-ff2a-5bb6-a4b7-231408d09159'::uuid, 'Selon Arendt, il faut choisir entre transmettre le monde et le renouveler.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle refuse l’alternative : on transmet PARCE QUE le monde sera renouvelé.', 7),
    ('1ab5c720-0aa9-58ee-8444-e18db92d7dc7'::uuid, '91cfcb3f-ff2a-5bb6-a4b7-231408d09159'::uuid, 'Que signifie l’étymologie « educere » ?', 'mcq', '["Conduire hors de","Nourrir","Instruire","Corriger"]'::jsonb, 0, 'Face à *educare*, « élever, nourrir » : deux gestes en tension.', 8),
    ('024faada-c941-5dc9-8986-471ed21dc10d'::uuid, '2bfb3860-f611-5bcd-8c80-bff54e2364bf'::uuid, 'Dans le « Phèdre », l’écriture est comparée à…', 'mcq', '["Un pharmakon : remède et poison","Un miroir","Une cité","Un jardin"]'::jsonb, 0, 'Le mythe de Theuth : elle affaiblit la mémoire tout en la fixant.', 1),
    ('3100ffc7-788e-5e5b-92ac-25d7298b0ed6'::uuid, '2bfb3860-f611-5bcd-8c80-bff54e2364bf'::uuid, 'Gutenberg met au point l’imprimerie vers 1450.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le livre devient reproductible, vérifiable, discutable.', 2),
    ('96e5f014-0107-5d33-8c0a-963c41e55051'::uuid, '2bfb3860-f611-5bcd-8c80-bff54e2364bf'::uuid, 'Que désigne l’habitus chez Bourdieu ?', 'mcq', '["Des dispositions incorporées, transmises sans être enseignées","Un règlement scolaire","Un programme officiel","Une méthode de lecture"]'::jsonb, 0, 'Façons de parler, de se tenir, goûts : elles pèsent sur la réussite.', 3),
    ('e06ba6ed-095b-53a6-9d68-cce0297a427e'::uuid, '2bfb3860-f611-5bcd-8c80-bff54e2364bf'::uuid, 'Selon Michel Serres, que faut-il transmettre à « Petite Poucette » ?', 'mcq', '["La capacité à s’orienter dans un savoir déjà accessible","Davantage de contenus à mémoriser","Rien du tout","Uniquement des savoir-faire manuels"]'::jsonb, 0, 'Le savoir est disponible ; ce qui manque, c’est le tri et la mise en ordre.', 4),
    ('666332b1-ab4c-5ade-bfaf-ff172a4611b1'::uuid, '2bfb3860-f611-5bcd-8c80-bff54e2364bf'::uuid, 'Halbwachs montre que la mémoire individuelle s’appuie sur des cadres sociaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une société transmet aussi ce qu’elle décide de commémorer — et d’oublier.', 5),
    ('4166960f-987c-5b04-9877-23d7fe089d16'::uuid, '2bfb3860-f611-5bcd-8c80-bff54e2364bf'::uuid, '« Traduttore, traditore » signifie…', 'mcq', '["Traduire, c’est trahir","Traduire, c’est créer","Le traducteur est un traître à sa patrie","La traduction est impossible"]'::jsonb, 0, 'Toute transmission déforme, et c’est ce qui la maintient vivante.', 6),
    ('a0ea3e27-a0d4-59cd-849c-766a5a4fa074'::uuid, '2bfb3860-f611-5bcd-8c80-bff54e2364bf'::uuid, 'Le savoir se transmet exactement comme un objet passe de main en main.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il doit être reconstruit par celui qui l’acquiert.', 7),
    ('e5b13360-e5a6-5651-a9ac-08a11b4f5c79'::uuid, '2bfb3860-f611-5bcd-8c80-bff54e2364bf'::uuid, 'Selon Thamous, quel est le danger de l’écriture ?', 'mcq', '["Croire savoir sans savoir","Coûter trop cher","Être illisible","Être réservée aux prêtres"]'::jsonb, 0, 'Les hommes se fieront aux signes extérieurs au lieu de se souvenir.', 8),
    ('b5b0929d-4315-555b-9516-d38c1a9e125e'::uuid, '2d41ff68-c753-5190-a5d8-2c7db76d0ca8'::uuid, 'Comment Kant définit-il les Lumières ?', 'mcq', '["La sortie de l’homme hors de l’état de minorité dont il est responsable","Le progrès des sciences","La victoire de la raison sur la religion","Le règne des philosophes"]'::jsonb, 0, 'D’où le mot d’ordre *Sapere aude* : ose savoir.', 1),
    ('444de7aa-b214-522c-bcce-acb28f12bf2f'::uuid, '2d41ff68-c753-5190-a5d8-2c7db76d0ca8'::uuid, 'Chez Kant, la minorité est un état dont nous sommes responsables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce n’est pas la nature qui nous y maintient mais la paresse et la lâcheté.', 2),
    ('57254a83-8063-5556-81c7-34b8c4e5deb3'::uuid, '2d41ff68-c753-5190-a5d8-2c7db76d0ca8'::uuid, 'Quelle hypothèse Rancière tire-t-il du « Maître ignorant » ?', 'mcq', '["L’égalité des intelligences, à poser au départ","La supériorité du maître","L’inutilité de l’école","La nécessité de la sélection"]'::jsonb, 0, 'Un maître qui explique installe la dépendance qu’il prétend guérir.', 3),
    ('85e3fc9d-2db0-5fce-90dc-817a186ace6c'::uuid, '2d41ff68-c753-5190-a5d8-2c7db76d0ca8'::uuid, 'En quelle année les femmes obtiennent-elles le droit de vote en France ?', 'mcq', '["1944","1918","1936","1965"]'::jsonb, 0, 'La capacité de travailler sans autorisation maritale date, elle, de 1965.', 4),
    ('62da0fae-df73-5186-99bf-558db9da2ebb'::uuid, '2d41ff68-c753-5190-a5d8-2c7db76d0ca8'::uuid, 'Frantz Fanon analyse le coût psychique de la colonisation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Notamment dans *Les Damnés de la terre* (1961).', 5),
    ('7e566eaf-cf6a-5277-8abc-532e1fae7941'::uuid, '2d41ff68-c753-5190-a5d8-2c7db76d0ca8'::uuid, 'Que signifie la formule de Beauvoir « On ne naît pas femme : on le devient » ?', 'mcq', '["Ce qui est construit socialement peut être défait","La biologie détermine tout","Les femmes doivent imiter les hommes","Le genre n’existe pas"]'::jsonb, 0, '*Le Deuxième Sexe*, 1949 : la condition féminine est un produit historique.', 6),
    ('a65503d0-0e91-52fe-a92e-ab98b94407ec'::uuid, '2d41ff68-c753-5190-a5d8-2c7db76d0ca8'::uuid, 'Toute émancipation est exempte de contrainte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’école obligatoire arrache l’enfant au travail, mais aussi à sa famille.', 7),
    ('fe499e9a-de03-5e6f-8df3-db001e0ebeeb'::uuid, '2d41ff68-c753-5190-a5d8-2c7db76d0ca8'::uuid, 'L’étymologie d’« émanciper » renvoie…', 'mcq', '["À la sortie de la main du père (manus)","À la libération d’une prison","À l’adolescence","Au vote"]'::jsonb, 0, 'Terme de droit romain, devenu politique puis individuel.', 8),
    ('b08510e5-2f16-53e6-a58f-ac967a57fec2'::uuid, '959e99ff-8bd3-591e-8d5d-1e338f986596'::uuid, 'De quel poète est le vers « Un seul être vous manque et tout est dépeuplé » ?', 'mcq', '["Lamartine","Hugo","Musset","Baudelaire"]'::jsonb, 0, '« L’Isolement », *Méditations poétiques*, 1820.', 1),
    ('0cae508e-eb87-52b3-bec1-21a0d6b5c449'::uuid, '959e99ff-8bd3-591e-8d5d-1e338f986596'::uuid, 'Quelle œuvre de Chateaubriand fixe la figure du « mal du siècle » ?', 'mcq', '["René","Atala","Les Martyrs","Le Génie du christianisme"]'::jsonb, 0, 'Un « vague des passions » : le désir devance toute expérience possible.', 2),
    ('172b0079-7892-51c8-85d2-3414a4fc28c6'::uuid, '959e99ff-8bd3-591e-8d5d-1e338f986596'::uuid, 'Le romantisme fait de la passion une source de vérité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Là où l’âge classique y voyait un désordre à corriger par la raison.', 3),
    ('a14f8065-5922-55e6-829f-13a4fd5472b3'::uuid, '959e99ff-8bd3-591e-8d5d-1e338f986596'::uuid, 'Comment Musset explique-t-il historiquement le mal du siècle ?', 'mcq', '["Une génération née « entre deux mondes », après l’Empire","Une crise économique","La perte de la foi seule","L’industrialisation"]'::jsonb, 0, '*La Confession d’un enfant du siècle*, 1836.', 4),
    ('bb09ab72-797e-5008-b63b-28a30ca74d54'::uuid, '959e99ff-8bd3-591e-8d5d-1e338f986596'::uuid, 'Que reproche Hegel à l’« âme belle » romantique ?', 'mcq', '["Elle préfère sa pureté à l’action","Elle est trop rationnelle","Elle méprise la nature","Elle refuse la poésie"]'::jsonb, 0, 'Elle se complaît dans son insatisfaction plutôt que d’agir.', 5),
    ('5cc93282-ff80-5013-bf78-75beb7901592'::uuid, '959e99ff-8bd3-591e-8d5d-1e338f986596'::uuid, 'Chez les romantiques, la nature n’est qu’un décor.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle répond au sentiment et garde la mémoire : « Le Lac », « Tristesse d’Olympio ».', 6),
    ('bcc37d22-c35e-5fed-8f27-844ee711f3b3'::uuid, '959e99ff-8bd3-591e-8d5d-1e338f986596'::uuid, 'Comment la psychanalyse relit-elle la mélancolie ?', 'mcq', '["Comme un deuil impossible, dont l’objet est inconnu","Comme une force créatrice pure","Comme une maladie du foie","Comme une posture sociale"]'::jsonb, 0, 'Le mélancolique ne sait pas ce qu’il a perdu.', 7),
    ('ef3eb872-05bb-554d-8960-0d58f93d1ea3'::uuid, '959e99ff-8bd3-591e-8d5d-1e338f986596'::uuid, 'Nietzsche distingue un romantisme de la détresse et un art de la surabondance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et il ne cache pas sa préférence pour le second.', 8),
    ('c521ad17-1528-57a2-acbf-e38cc64f8940'::uuid, '6ba9963d-1c2c-5483-bf75-50197e7431bb'::uuid, 'Pour les stoïciens, la passion est…', 'mcq', '["Un jugement faux sur les choses","Une maladie du corps","Un don divin","Une force à cultiver"]'::jsonb, 0, 'Épictète : ce n’est pas la chose qui trouble, mais l’opinion qu’on en a.', 1),
    ('1a33bbca-48b7-5b99-972e-4db690202225'::uuid, '6ba9963d-1c2c-5483-bf75-50197e7431bb'::uuid, 'Descartes condamne les passions comme entièrement mauvaises.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il les dit « toutes bonnes de leur nature » : il faut en être maître, non les fuir.', 2),
    ('1add9a22-bbc9-5b3c-95e2-e639a9bfefc1'::uuid, '6ba9963d-1c2c-5483-bf75-50197e7431bb'::uuid, 'Que soutient Hume sur le rapport entre raison et passions ?', 'mcq', '["La raison est l’esclave des passions : elle calcule les moyens, pas les fins","La raison doit dominer les passions","Passions et raison sont identiques","Les passions n’existent pas"]'::jsonb, 0, 'Seul un sentiment peut nous faire vouloir quelque chose.', 3),
    ('c791f742-65a5-58fe-bf4c-ebbae786d9c6'::uuid, '6ba9963d-1c2c-5483-bf75-50197e7431bb'::uuid, 'Qu’observe Damasio chez les patients aux circuits émotionnels lésés ?', 'mcq', '["Ils deviennent incapables de décider","Ils raisonnent mieux","Ils perdent la mémoire","Ils deviennent violents"]'::jsonb, 0, '*L’Erreur de Descartes* : l’émotion est une condition du raisonnement pratique.', 4),
    ('6d261916-c525-5d41-bb0a-021db5e559af'::uuid, '6ba9963d-1c2c-5483-bf75-50197e7431bb'::uuid, 'Pascal fait du « cœur » un éloge de l’irrationnel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il décrit un ordre de connaissance immédiate, distinct de la démonstration.', 5),
    ('731a1668-cccf-5749-b7b6-bd2a8ad29c41'::uuid, '6ba9963d-1c2c-5483-bf75-50197e7431bb'::uuid, 'Chez Rousseau, quel sentiment fonde la morale avant toute réflexion ?', 'mcq', '["La pitié","L’orgueil","La honte","La colère"]'::jsonb, 0, 'La répugnance naturelle à voir souffrir son semblable.', 6),
    ('12cbf17e-b2df-5e22-a99b-f48c17ad77d5'::uuid, '6ba9963d-1c2c-5483-bf75-50197e7431bb'::uuid, 'Martha Nussbaum décrit les émotions comme des jugements de valeur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avoir peur, c’est juger qu’une chose importante est menacée.', 7),
    ('6707fa26-62cb-515b-8c91-c3dcb202165d'::uuid, '6ba9963d-1c2c-5483-bf75-50197e7431bb'::uuid, 'Dans le « Phèdre », l’âme est figurée par…', 'mcq', '["Un attelage conduit par un cocher","Un navire sans pilote","Une cité en guerre","Un miroir brisé"]'::jsonb, 0, 'La raison mène deux chevaux, dont l’un tire vers le bas.', 8),
    ('37df9bfc-61b7-507b-a6e5-3c7d74efad75'::uuid, '7b1b0ae7-c402-55d2-a3cd-539fcd5726c6'::uuid, 'Pourquoi Platon veut-il régler les modes musicaux dans la cité ?', 'mcq', '["La musique éduque l’âme : c’est une affaire politique","Elle coûte trop cher","Elle distrait des mathématiques","Elle est réservée aux dieux"]'::jsonb, 0, 'Certains modes amollissent, d’autres fortifient.', 1),
    ('a9499973-3d58-55ee-88ec-404231a465cb'::uuid, '7b1b0ae7-c402-55d2-a3cd-539fcd5726c6'::uuid, 'Que représente la musique selon Schopenhauer ?', 'mcq', '["La volonté elle-même, fond du monde","Les apparences sensibles","Les idées mathématiques","Rien du tout"]'::jsonb, 0, 'D’où sa place à part parmi les arts.', 2),
    ('94a27c60-9ebd-5ca6-ab7d-a9821700ef08'::uuid, '7b1b0ae7-c402-55d2-a3cd-539fcd5726c6'::uuid, 'Chez Kant, le sublime commence par un déplaisir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Nous mesurons notre petitesse, avant que la raison ne conçoive l’infini.', 3),
    ('be1928d3-215c-5c41-bce0-c98067b6d54c'::uuid, '7b1b0ae7-c402-55d2-a3cd-539fcd5726c6'::uuid, 'Quel est le paradoxe kantien du jugement de goût ?', 'mcq', '["Il est subjectif mais prétend à l’universalité","Il est objectif et privé","Il est purement rationnel","Il ne concerne que l’artiste"]'::jsonb, 0, 'On dit « c’est beau », non « ça me plaît ».', 4),
    ('71bb2c75-fe32-5666-9175-54ad665b44fd'::uuid, '7b1b0ae7-c402-55d2-a3cd-539fcd5726c6'::uuid, 'La catharsis désigne chez Aristote…', 'mcq', '["La purgation des passions par la fiction tragique","La purification religieuse","L’imitation de la nature","La règle des trois unités"]'::jsonb, 0, 'On éprouve les passions à distance protégée.', 5),
    ('6f102231-d90c-518d-9eaa-524781302759'::uuid, '7b1b0ae7-c402-55d2-a3cd-539fcd5726c6'::uuid, 'Adorno voit dans l’industrie culturelle une libération de la sensibilité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il y dénonce au contraire une standardisation de l’écoute.', 6),
    ('1e613427-dacb-552e-9ddc-937aff3aeca2'::uuid, '7b1b0ae7-c402-55d2-a3cd-539fcd5726c6'::uuid, 'Que montre Bourdieu dans « La Distinction » ?', 'mcq', '["Les goûts fonctionnent comme des marqueurs sociaux","Le goût est inné","Tous les goûts se valent","La musique échappe au social"]'::jsonb, 0, 'Ce qu’on trouve beau dit d’où l’on vient.', 7),
    ('d866c159-7125-5d09-bb29-7557425664a9'::uuid, '7b1b0ae7-c402-55d2-a3cd-539fcd5726c6'::uuid, 'Saint Augustin s’inquiète de prendre plus de plaisir au chant qu’au texte sacré.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La musique agit avant le sens : c’est ce qui l’inquiète.', 8),
    ('b5cbb266-a3c4-5557-ae42-af2c3697d5c2'::uuid, 'fd743724-e8b6-596d-987d-637ef8b0dd81'::uuid, 'Quel ouvrage inaugure l’écriture de l’intériorité au IVe siècle ?', 'mcq', '["Les Confessions de saint Augustin","Les Essais de Montaigne","Le Discours de la méthode","La République"]'::jsonb, 0, '*In interiore homine habitat veritas.*', 1),
    ('e0f70087-071d-51ab-8555-c55dae50b316'::uuid, 'fd743724-e8b6-596d-987d-637ef8b0dd81'::uuid, 'Que dit Montaigne de son projet dans les « Essais » ?', 'mcq', '["« Je suis moi-même la matière de mon livre »","« Je pense donc je suis »","« Connais-toi toi-même »","« L’enfer, c’est les autres »"]'::jsonb, 0, 'Et il ajoute : « Je ne peins pas l’être, je peins le passage. »', 2),
    ('22ab8e6e-f01d-59df-8900-3a10a427ee33'::uuid, 'fd743724-e8b6-596d-987d-637ef8b0dd81'::uuid, 'Chez Descartes, le moi est une substance pensante transparente à elle-même.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est cette transparence que Marx, Nietzsche et Freud contesteront.', 3),
    ('05f428cd-bf5b-5058-a70f-cff09f072b5e'::uuid, 'fd743724-e8b6-596d-987d-637ef8b0dd81'::uuid, 'Quelles sont les trois « blessures narcissiques » selon Freud ?', 'mcq', '["Copernic, Darwin, la psychanalyse","Platon, Descartes, Kant","Galilée, Newton, Einstein","Marx, Nietzsche, Freud"]'::jsonb, 0, 'Décentrement cosmologique, biologique, puis psychique.', 4),
    ('88a36867-1a9c-50a5-b23f-b29b0ea5522b'::uuid, 'fd743724-e8b6-596d-987d-637ef8b0dd81'::uuid, 'Pour Nietzsche, le « je » est une fiction grammaticale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une cause inventée derrière l’action, par habitude de langage.', 5),
    ('8853aa52-8d8e-5a03-9b72-7668b30740ae'::uuid, 'fd743724-e8b6-596d-987d-637ef8b0dd81'::uuid, 'Que signifie « l’existence précède l’essence » chez Sartre ?', 'mcq', '["L’homme n’a pas de nature donnée : il se fait","L’être précède la pensée","Le corps précède l’âme","La société précède l’individu"]'::jsonb, 0, 'D’où la responsabilité entière du sujet sur ce qu’il devient.', 6),
    ('5b9727fb-6225-5965-a839-3f96e34c9006'::uuid, 'fd743724-e8b6-596d-987d-637ef8b0dd81'::uuid, 'Le « connais-toi toi-même » socratique invite à l’introspection psychologique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il invite à mesurer ce que l’on sait et ce que l’on ignore.', 7),
    ('fee515c2-fbc6-5ceb-9272-061c504a91a8'::uuid, 'fd743724-e8b6-596d-987d-637ef8b0dd81'::uuid, 'Selon Marx, la conscience est déterminée par…', 'mcq', '["Les conditions matérielles d’existence","L’inconscient","Le langage seul","La volonté divine"]'::jsonb, 0, 'Ce n’est pas la conscience qui détermine la vie, mais la vie la conscience.', 8),
    ('e74590d3-e9e5-54c3-8e87-396b96c38f47'::uuid, '61343b45-e6c4-5b55-bed0-14a140ba0ada'::uuid, 'Sur quoi Locke fonde-t-il l’identité personnelle ?', 'mcq', '["La conscience et la mémoire","La substance corporelle","Le nom propre","La communauté"]'::jsonb, 0, 'Ce qui relie les moments, c’est la conscience qu’on en garde.', 1),
    ('bb84b85f-57af-5997-9a0f-609d14485eeb'::uuid, '61343b45-e6c4-5b55-bed0-14a140ba0ada'::uuid, 'Que trouve Hume lorsqu’il cherche son moi par introspection ?', 'mcq', '["Un faisceau de perceptions, jamais un moi","Une substance pensante","Une âme immortelle","Rien du tout, littéralement"]'::jsonb, 0, 'L’unité du moi serait une fiction utile.', 2),
    ('8bd2465e-334e-59e1-9462-8fb6be8e4fae'::uuid, '61343b45-e6c4-5b55-bed0-14a140ba0ada'::uuid, 'Ricœur distingue la mêmeté (idem) et l’ipséité (ipse).', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’identité narrative est le lieu où les deux se nouent.', 3),
    ('58c72aff-260d-5607-99e4-7b95c3a0fa7c'::uuid, '61343b45-e6c4-5b55-bed0-14a140ba0ada'::uuid, 'Que soutient Judith Butler sur le genre ?', 'mcq', '["Il est performatif : une série d’actes répétés","Il est purement biologique","Il est un choix libre et instantané","Il n’a aucune réalité"]'::jsonb, 0, 'La répétition produit l’illusion d’une nature — et permet le déplacement.', 4),
    ('43d58fb8-8c31-5ff9-94f0-4ef80919aae6'::uuid, '61343b45-e6c4-5b55-bed0-14a140ba0ada'::uuid, 'Dire qu’une chose est socialement construite signifie qu’elle est irréelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une construction sociale est réelle et contraignante.', 5),
    ('b2adedd3-ced8-5410-9f3b-4b079cb77793'::uuid, '61343b45-e6c4-5b55-bed0-14a140ba0ada'::uuid, 'Que met en garde Amin Maalouf dans « Les Identités meurtrières » ?', 'mcq', '["Contre l’identité réduite à une seule appartenance","Contre le métissage","Contre les langues étrangères","Contre la mémoire collective"]'::jsonb, 0, 'C’est la réduction à une appartenance unique qui rend l’identité meurtrière.', 6),
    ('000ad8da-c053-57ba-b4ac-73f07bacd6a6'::uuid, '61343b45-e6c4-5b55-bed0-14a140ba0ada'::uuid, 'Chez Sartre, une identité peut être imposée par le regard d’autrui.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Réflexions sur la question juive* : c’est l’antisémite qui fait le Juif.', 7),
    ('efffbd28-470d-51b7-ba30-bb90c2026f7e'::uuid, '61343b45-e6c4-5b55-bed0-14a140ba0ada'::uuid, 'Quel roman de Virginia Woolf met en scène un personnage qui change de sexe ?', 'mcq', '["Orlando","Mrs Dalloway","La Promenade au phare","Les Vagues"]'::jsonb, 0, 'Publié en 1928, il traverse plusieurs siècles.', 8),
    ('a3508d4a-bf0a-51dd-b02f-349c67744155'::uuid, '00db664e-04d9-5a9c-9df0-bb1d27331198'::uuid, 'Que représente le visage chez Levinas ?', 'mcq', '["Ce qui m’oblige, et me dit « tu ne tueras point »","Un simple objet de perception","Un masque social","Une image trompeuse"]'::jsonb, 0, 'D’où la gravité particulière de la mutilation faciale.', 1),
    ('ce5fe959-7f87-59a8-bef4-4d7b975dac21'::uuid, '00db664e-04d9-5a9c-9df0-bb1d27331198'::uuid, 'Quel roman de Pierre Lemaitre met en scène un soldat défiguré ?', 'mcq', '["Au revoir là-haut","Le Feu","Les Croix de bois","Voyage au bout de la nuit"]'::jsonb, 0, 'Prix Goncourt 2013 : son héros se fabrique des masques.', 2),
    ('0ac58b91-3747-5bcf-a7b0-29a6f76a4aa6'::uuid, '00db664e-04d9-5a9c-9df0-bb1d27331198'::uuid, 'Selon Merleau-Ponty, on a un corps comme on possède un objet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On EST son corps : c’est par lui qu’on habite le monde.', 3),
    ('163b2bc4-1840-5393-ab3e-6f9e23e77e0b'::uuid, '00db664e-04d9-5a9c-9df0-bb1d27331198'::uuid, 'Que vise la prison moderne selon Foucault ?', 'mcq', '["L’âme, par la discipline et la surveillance","Le corps, par le supplice","La fortune du condamné","La famille du détenu"]'::jsonb, 0, '*Surveiller et punir*, 1975.', 4),
    ('52bf03d8-e83a-50b9-b65b-5f0a269cf969'::uuid, '00db664e-04d9-5a9c-9df0-bb1d27331198'::uuid, 'Le panoptique fait que le détenu finit par se surveiller lui-même.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il peut être vu à tout moment sans savoir quand : le pouvoir devient intérieur.', 5),
    ('8a2affd0-4aea-5aa6-85df-4d2e3c8bf80e'::uuid, '00db664e-04d9-5a9c-9df0-bb1d27331198'::uuid, 'Que décrit Primo Levi dans « Si c’est un homme » ?', 'mcq', '["La « démolition d’un homme » : le nom remplacé par un numéro","La libération des camps","Le procès de Nuremberg","La vie d’après-guerre"]'::jsonb, 0, 'Le camp détruit la personne avant de détruire le corps.', 6),
    ('cd94ebd9-5dd2-55f1-9b57-695762d0ba11'::uuid, '00db664e-04d9-5a9c-9df0-bb1d27331198'::uuid, 'Quelle conclusion Robert Antelme tire-t-il de l’expérience concentrationnaire ?', 'mcq', '["Il n’existe pas plusieurs espèces humaines","Les bourreaux ne sont pas humains","La littérature est impossible","Le témoignage est inutile"]'::jsonb, 0, '*L’Espèce humaine* (1947) : c’est ce que le bourreau tentait de nier.', 7),
    ('fde2b41e-cff8-5868-83d8-fdabcdc1ad14'::uuid, '00db664e-04d9-5a9c-9df0-bb1d27331198'::uuid, 'Le « membre fantôme » montre un écart entre corps vécu et corps objectif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’un des arguments cliniques de la phénoménologie du corps.', 8),
    ('e00389ad-7325-526e-99a0-365270f2cf9f'::uuid, 'ee347b3c-5793-5dab-aea0-a8959669c3d3'::uuid, 'Quel critère Popper propose-t-il pour distinguer la science ?', 'mcq', '["La falsifiabilité : une théorie doit pouvoir être réfutée","La vérifiabilité","L’utilité pratique","Le consensus des savants"]'::jsonb, 0, 'Une théorie qui explique tout n’est pas plus forte : elle sort du champ.', 1),
    ('70e7d932-3dd4-5296-84a9-91b3cd967a56'::uuid, 'ee347b3c-5793-5dab-aea0-a8959669c3d3'::uuid, 'Une théorie réfutable est une théorie fausse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est simplement testable : c’est ce qui la rend scientifique.', 2),
    ('5e7d1430-fc37-5c08-a418-7dd5afd8e0a6'::uuid, 'ee347b3c-5793-5dab-aea0-a8959669c3d3'::uuid, 'Que désigne un « paradigme » chez Kuhn ?', 'mcq', '["Un cadre partagé de problèmes et de méthodes","Une opinion majoritaire","Une hypothèse isolée","Un instrument de mesure"]'::jsonb, 0, 'Les révolutions scientifiques sont des changements de paradigme.', 3),
    ('5cc9bb94-f9ed-5154-a464-f04547268090'::uuid, 'ee347b3c-5793-5dab-aea0-a8959669c3d3'::uuid, 'Selon Bachelard, le sens commun est un point de départ pour la science.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un obstacle épistémologique : la science se construit contre lui.', 4),
    ('2d444a28-379f-5dfd-a662-d939d6341435'::uuid, 'ee347b3c-5793-5dab-aea0-a8959669c3d3'::uuid, 'En quoi consiste le problème de l’induction posé par Hume ?', 'mcq', '["Aucune série d’observations ne prouve une loi générale","Les instruments sont imprécis","Les savants se trompent","Les mathématiques sont abstraites"]'::jsonb, 0, 'Toute science empirique repose donc sur un pari.', 5),
    ('4032724d-594a-56d1-a560-50d1b6c584e7'::uuid, 'ee347b3c-5793-5dab-aea0-a8959669c3d3'::uuid, 'Peut-on déduire un devoir d’un fait scientifique ?', 'mcq', '["Non : une donnée n’énonce aucune politique","Oui, toujours","Oui, en science physique","Oui, si les données sont sûres"]'::jsonb, 0, 'C’est la loi de Hume, reprise par Weber sous le nom de neutralité axiologique.', 6),
    ('0f5d969c-6ba2-5cfe-a693-dcf5b691058e'::uuid, 'ee347b3c-5793-5dab-aea0-a8959669c3d3'::uuid, 'Pour Popper, le progrès scientifique se fait par conjectures et réfutations.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne prouve jamais définitivement : on élimine ce qui résiste mal.', 7),
    ('e8556891-70c1-5674-8db9-e7a0d676b803'::uuid, 'ee347b3c-5793-5dab-aea0-a8959669c3d3'::uuid, 'Quelle formule résume la position de Bachelard ?', 'mcq', '["« Le fait scientifique est conquis, construit, constaté »","« Tout est relatif »","« La nature est un livre écrit en langage mathématique »","« Je ne feins pas d’hypothèses »"]'::jsonb, 0, 'Le fait n’est jamais donné : il est produit par une méthode.', 8),
    ('8af5fa53-311b-5664-b6f3-35eec201e19f'::uuid, '362a74dc-10c2-5205-8ef9-6c5667ff260b'::uuid, 'Que déplace le ready-made de Duchamp ?', 'mcq', '["Ce n’est plus le faire qui fait l’œuvre, mais le choix et le contexte","La technique picturale","Le prix des œuvres","La durée de conservation"]'::jsonb, 0, '*Fountain*, 1917 : un urinoir renversé et signé.', 1),
    ('2f3719ea-203b-5519-a971-fed785e49e22'::uuid, '362a74dc-10c2-5205-8ef9-6c5667ff260b'::uuid, 'Quelle invention rend l’imitation techniquement caduque au XIXe siècle ?', 'mcq', '["La photographie","Le cinéma","La lithographie","L’imprimerie"]'::jsonb, 0, 'Si la machine copie mieux, l’art doit chercher ailleurs.', 2),
    ('6ebaa49d-40ad-53e3-9f28-343c40bb964b'::uuid, '362a74dc-10c2-5205-8ef9-6c5667ff260b'::uuid, 'Devant les « Boîtes Brillo », Danto constate que la différence est visible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Rien de visible ne distingue l’œuvre du produit : la différence est théorique.', 3),
    ('24e85358-e9d7-534b-8347-e5c39acf6ef8'::uuid, '362a74dc-10c2-5205-8ef9-6c5667ff260b'::uuid, 'Que désigne l’« aura » chez Walter Benjamin ?', 'mcq', '["L’unicité de l’œuvre, liée à un ici et maintenant","La renommée de l’artiste","La lumière du tableau","Le prix de vente"]'::jsonb, 0, 'La reproductibilité technique la fait perdre — et ouvre un usage politique.', 4),
    ('239c3c4e-67ef-54e7-9bfe-43a3947e84f9'::uuid, '362a74dc-10c2-5205-8ef9-6c5667ff260b'::uuid, 'Selon la définition institutionnelle de Dickie, est art…', 'mcq', '["Ce qu’un monde de l’art traite comme tel","Ce qui est beau","Ce qui est bien fait","Ce qui plaît au public"]'::jsonb, 0, 'La définition déplace le critère de l’objet vers l’institution.', 5),
    ('6d57c0f7-2fef-5167-b064-e8d505cb2c40'::uuid, '362a74dc-10c2-5205-8ef9-6c5667ff260b'::uuid, 'Adorno estime que la culture de masse démocratise l’art.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il y voit une standardisation, contre l’optimisme de Benjamin.', 6),
    ('32e09f88-b205-5a8f-b5a9-44c6f642d634'::uuid, '362a74dc-10c2-5205-8ef9-6c5667ff260b'::uuid, 'Depuis Aristote, l’art était défini comme…', 'mcq', '["Mimesis, imitation de la nature","Expression du moi","Production de beauté pure","Artisanat utile"]'::jsonb, 0, 'C’est cette définition que le XXe siècle congédie.', 7),
    ('fd5f5302-c205-59bf-bf28-04819f5aa094'::uuid, '362a74dc-10c2-5205-8ef9-6c5667ff260b'::uuid, 'Les avant-gardes transgressives ont fini par entrer au musée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où la question : une transgression devenue canonique en est-elle encore une ?', 8),
    ('fa0d182b-9b45-5d63-9125-13c9820a59a7'::uuid, '018cc9fd-b6f4-506f-ae89-6a6d3c9b69ab'::uuid, 'Pourquoi Adorno et Horkheimer parlent-ils d’« industrie culturelle » ?', 'mcq', '["Parce que les masses ne produisent pas cette culture, elles la reçoivent","Parce qu’elle emploie des ouvriers","Parce qu’elle est peu coûteuse","Parce qu’elle est récente"]'::jsonb, 0, 'Le terme est choisi contre celui de « culture de masse ».', 1),
    ('39685594-f6d4-5106-9bba-ad0c019e7ded'::uuid, '018cc9fd-b6f4-506f-ae89-6a6d3c9b69ab'::uuid, 'Que désigne la « pseudo-individualisation » ?', 'mcq', '["Des variantes de surface qui simulent le choix","La personnalisation réelle des œuvres","L’anonymat des créateurs","La signature des artistes"]'::jsonb, 0, 'Elle accompagne la standardisation des formes.', 2),
    ('977c5ac9-54f3-5cf2-b47a-0da8f408d080'::uuid, '018cc9fd-b6f4-506f-ae89-6a6d3c9b69ab'::uuid, 'Umberto Eco oppose radicalement lucides et naïfs face à la culture de masse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il refuse ce partage : *Apocalittici e integrati*, 1964.', 3),
    ('f9c54584-28fc-59f4-95f8-53d8cf67481c'::uuid, '018cc9fd-b6f4-506f-ae89-6a6d3c9b69ab'::uuid, 'Que montre Stuart Hall sur la réception des messages ?', 'mcq', '["Elle peut être dominante, négociée ou oppositionnelle","Elle est toujours passive","Elle est identique pour tous","Elle dépend du seul niveau de diplôme"]'::jsonb, 0, 'Le public réinterprète ce qu’il reçoit.', 4),
    ('b0668b89-c0aa-5669-ac6b-536c1711e2fc'::uuid, '018cc9fd-b6f4-506f-ae89-6a6d3c9b69ab'::uuid, 'Michel de Certeau appelle « braconnage »…', 'mcq', '["Le détournement et le réemploi par l’usager","Le piratage informatique","La copie illégale","La critique universitaire"]'::jsonb, 0, '*L’Invention du quotidien*, 1980.', 5),
    ('ac59db21-5629-55e2-aab9-58013e9fc320'::uuid, '018cc9fd-b6f4-506f-ae89-6a6d3c9b69ab'::uuid, 'Selon Bourdieu, la légitimité culturelle est une propriété des œuvres.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un rapport de force symbolique, qui reconduit les hiérarchies sociales.', 6),
    ('3b8fa40b-4c32-5d84-9f47-77cbfda50a0a'::uuid, '018cc9fd-b6f4-506f-ae89-6a6d3c9b69ab'::uuid, 'Qui analyse le catch et le bifteck-frites comme des mythologies modernes ?', 'mcq', '["Roland Barthes","Pierre Bourdieu","Theodor Adorno","Umberto Eco"]'::jsonb, 0, '*Mythologies*, 1957.', 7),
    ('fc75d9d4-56af-5efc-91f1-eecc224399c1'::uuid, '018cc9fd-b6f4-506f-ae89-6a6d3c9b69ab'::uuid, 'Le roman et le cinéma ont d’abord été des divertissements suspects.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les frontières de la légitimité culturelle se déplacent avec le temps.', 8),
    ('81ab35e4-88e8-5ffd-bfc6-04390bf2a2d8'::uuid, '0af72092-e7aa-563f-849d-e9a802fcec55'::uuid, 'Qui invente le mot « utopie » et en quelle année ?', 'mcq', '["Thomas More, en 1516","Platon, au IVe siècle av. J.-C.","Orwell, en 1949","Campanella, en 1602"]'::jsonb, 0, 'Du grec *ou-topos* : le lieu de nulle part.', 1),
    ('0c81b4f8-fae2-5da8-876e-2e4d01d52b48'::uuid, '0af72092-e7aa-563f-849d-e9a802fcec55'::uuid, 'Quel roman de 1920 sert de matrice au genre dystopique ?', 'mcq', '["Nous autres, de Zamiatine","1984, d’Orwell","Le Meilleur des mondes, de Huxley","Fahrenheit 451, de Bradbury"]'::jsonb, 0, 'Des numéros, des maisons de verre, l’ablation de l’imagination.', 2),
    ('49eb291e-167d-5dd9-a428-3d3babdf0f30'::uuid, '0af72092-e7aa-563f-849d-e9a802fcec55'::uuid, 'Dans « Le Meilleur des mondes », la servitude passe par la terreur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle passe par le plaisir : conditionnement, castes, *soma*.', 3),
    ('7ad025b7-1ccd-538d-996c-3f23b7fd30f7'::uuid, '0af72092-e7aa-563f-849d-e9a802fcec55'::uuid, 'À quoi sert la novlangue dans « 1984 » ?', 'mcq', '["À rendre la dissidence impensable en appauvrissant le vocabulaire","À unifier les langues du monde","À simplifier l’administration","À protéger les secrets d’État"]'::jsonb, 0, 'Sans les mots pour la formuler, la contestation devient impossible.', 4),
    ('c2d7b18f-2dcb-5a1c-af51-4cde8d31774b'::uuid, '0af72092-e7aa-563f-849d-e9a802fcec55'::uuid, 'L’utopie et la dystopie partagent l’idée d’une organisation totale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La dystopie retourne contre l’utopie son propre principe.', 5),
    ('d2a03dac-8d16-5b5c-b7ae-c3386155a1ac'::uuid, '0af72092-e7aa-563f-849d-e9a802fcec55'::uuid, 'Quelle est la différence entre les avertissements d’Orwell et de Huxley ?', 'mcq', '["Orwell craint la peur, Huxley le plaisir","Orwell craint la technique, Huxley la religion","Ils disent la même chose","Orwell est optimiste"]'::jsonb, 0, 'Interdire les livres, ou faire que personne n’ait plus envie d’en lire.', 6),
    ('27e307e2-be4e-51e7-ab82-7ef4b4f3cd24'::uuid, '0af72092-e7aa-563f-849d-e9a802fcec55'::uuid, 'Hannah Arendt analyse le totalitarisme par l’idéologie, la terreur et la destruction de l’espace public.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Les Origines du totalitarisme*, 1951.', 7),
    ('a1e64678-7e82-53a9-bd94-a3d17dee0875'::uuid, '0af72092-e7aa-563f-849d-e9a802fcec55'::uuid, '« La Servante écarlate » est une dystopie de…', 'mcq', '["Margaret Atwood","Ray Bradbury","Philip K. Dick","Aldous Huxley"]'::jsonb, 0, 'Publiée en 1985, elle traite du contrôle des corps des femmes.', 8),
    ('15792a01-5531-54cb-84a1-e8f8078feb6e'::uuid, '524212ac-f0bf-5a56-9b38-9ff0f4f25261'::uuid, 'Comment Hobbes décrit-il l’état de nature ?', 'mcq', '["Une guerre de tous contre tous","Un âge d’or pacifique","Une société égalitaire","Un état inconnaissable"]'::jsonb, 0, 'La vie y est « solitaire, misérable, dangereuse, animale et brève ».', 1),
    ('ba225285-2af2-5299-a892-2afb52eb9209'::uuid, '524212ac-f0bf-5a56-9b38-9ff0f4f25261'::uuid, 'Rousseau partage le diagnostic de Hobbes sur l’état de nature.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pour lui, l’homme naturel est pacifique : c’est la société qui produit la violence.', 2),
    ('b8c82336-1f5f-5b7f-8815-d437f00d4f43'::uuid, '524212ac-f0bf-5a56-9b38-9ff0f4f25261'::uuid, 'Comment Weber définit-il l’État moderne ?', 'mcq', '["Par le monopole de la violence physique légitime","Par la démocratie","Par le territoire seul","Par la monnaie"]'::jsonb, 0, 'La violence n’a pas disparu : elle a été confisquée et encadrée.', 3),
    ('72711e1c-1424-590e-8804-fa4330ede322'::uuid, '524212ac-f0bf-5a56-9b38-9ff0f4f25261'::uuid, 'Que désigne la violence symbolique chez Bourdieu ?', 'mcq', '["Une domination acceptée par ceux qui la subissent","Les insultes verbales","La violence des images","Les menaces sans passage à l’acte"]'::jsonb, 0, 'Elle s’exerce grâce aux catégories partagées qui la font paraître naturelle.', 4),
    ('895a77ec-b092-5264-863f-b09718840f08'::uuid, '524212ac-f0bf-5a56-9b38-9ff0f4f25261'::uuid, 'Selon Girard, le désir mimétique conduit à la rivalité puis au bouc émissaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le sacrifice d’une victime arbitraire restaure l’unité du groupe.', 5),
    ('fdd1d4d1-38dc-52d1-91a7-aa8e3d74191e'::uuid, '524212ac-f0bf-5a56-9b38-9ff0f4f25261'::uuid, 'Que soutient Freud dans « Malaise dans la civilisation » ?', 'mcq', '["La civilisation s’obtient par le refoulement de l’agressivité","La civilisation supprime l’agressivité","La violence est purement culturelle","La guerre est impossible"]'::jsonb, 0, 'L’agressivité refoulée se retourne en culpabilité — et ressurgit.', 6),
    ('2afe1914-6905-58b9-a658-60ed0fb1148d'::uuid, '524212ac-f0bf-5a56-9b38-9ff0f4f25261'::uuid, 'Norbert Elias décrit une montée de l’autocontrôle dans les sociétés européennes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le « processus de civilisation ».', 7),
    ('c764b30d-736a-5949-9e9e-9e30627981c0'::uuid, '524212ac-f0bf-5a56-9b38-9ff0f4f25261'::uuid, 'La non-violence de Gandhi et King est…', 'mcq', '["Une stratégie organisée, non une passivité","Un refus de toute action","Une doctrine religieuse exclusivement","Une forme de résignation"]'::jsonb, 0, 'Elle vise à rendre visible la violence de l’adversaire.', 8),
    ('a8061bfe-a897-54fe-9544-0793426afda6'::uuid, '9a4859e4-7a0a-5abd-bbb5-53e71a186861'::uuid, 'Quel est l’objet réel de l’« Histoire de la folie » de Foucault ?', 'mcq', '["Le partage historique entre raison et déraison","Le traitement des maladies mentales","La biographie des aliénistes","La chimie des médicaments"]'::jsonb, 0, 'Comment une société décide de ce qui relève de l’entendement.', 1),
    ('f35e18b3-3df8-5cb3-a845-fe55a8f1191c'::uuid, '9a4859e4-7a0a-5abd-bbb5-53e71a186861'::uuid, 'De quand Foucault date-t-il le « grand renfermement » ?', 'mcq', '["1656, avec l’Hôpital général de Paris","1789","1848","1789 puis 1900"]'::jsonb, 0, 'On y enferme ensemble pauvres, oisifs, libertins et insensés.', 2),
    ('c12e2165-ea46-58a5-974b-e84342f9f1a1'::uuid, '9a4859e4-7a0a-5abd-bbb5-53e71a186861'::uuid, 'Le critère du grand renfermement était d’abord médical.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il était social et moral : l’incapacité de travailler.', 3),
    ('7b47c25b-d95a-5120-800e-4bec0a523138'::uuid, '9a4859e4-7a0a-5abd-bbb5-53e71a186861'::uuid, 'Comment Foucault relit-il le geste de Pinel libérant les aliénés ?', 'mcq', '["Une contrainte visible remplacée par une contrainte intériorisée","Une libération pure et simple","Un échec thérapeutique","Une invention légendaire"]'::jsonb, 0, 'Le regard médical installe un jugement moral permanent.', 4),
    ('53df1e7d-e8c6-5111-bda1-a9489b1a20c0'::uuid, '9a4859e4-7a0a-5abd-bbb5-53e71a186861'::uuid, 'Que désigne le « biopouvoir » chez Foucault ?', 'mcq', '["Un pouvoir qui prend en charge la vie, la santé, la population","Le pouvoir des biologistes","La domination de la nature","Le droit de vie et de mort du souverain"]'::jsonb, 0, 'Il agit par la norme plus que par l’interdiction.', 5),
    ('a2d0e9f4-7c1f-5e56-ae2d-d51fc71aceb1'::uuid, '9a4859e4-7a0a-5abd-bbb5-53e71a186861'::uuid, 'Derrida a objecté qu’on ne peut faire l’histoire de la folie dans le langage de la raison.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Objection célèbre, qui n’annule pas la méthode mais en marque la limite.', 6),
    ('47e9890c-4f62-5f16-944d-823c1dc52dca'::uuid, '9a4859e4-7a0a-5abd-bbb5-53e71a186861'::uuid, 'Avant l’âge classique, le fou était systématiquement enfermé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il circulait, et sa parole avait une place : Érasme, Shakespeare, la nef des fous.', 7),
    ('ba08bdf5-fa4f-5ba8-9904-a9ac35e6cffd'::uuid, '9a4859e4-7a0a-5abd-bbb5-53e71a186861'::uuid, 'Quel outil de méthode Foucault fournit-il pour un essai ?', 'mcq', '["Ne jamais tenir une catégorie pour naturelle","Toujours se fier aux statistiques","Refuser toute histoire","Faire confiance aux institutions"]'::jsonb, 0, 'Folie, délinquance, normalité sont des découpages historiques.', 8),
    ('eea7c588-5a47-5212-89d9-6d67a8f87e12'::uuid, 'd3d69ba9-deba-5641-91c1-ec343fa8c741'::uuid, 'Quel est le sous-titre de « Frankenstein » de Mary Shelley ?', 'mcq', '["Le Prométhée moderne","Le Docteur et le Monstre","La Créature","L’Apprenti sorcier"]'::jsonb, 0, 'Publié en 1818, il place le mythe grec au cœur de la modernité.', 1),
    ('627c7831-94f8-5f1c-8261-a5b2a231a4d2'::uuid, 'd3d69ba9-deba-5641-91c1-ec343fa8c741'::uuid, 'Quelle est la faute de Victor Frankenstein selon le roman ?', 'mcq', '["Avoir abandonné sa créature","Avoir créé un être vivant","Avoir étudié la médecine","Avoir désobéi à son père"]'::jsonb, 0, 'La question se déplace de la puissance vers la responsabilité.', 2),
    ('d6db6553-7b58-5704-bba2-d7aef7db4182'::uuid, 'd3d69ba9-deba-5641-91c1-ec343fa8c741'::uuid, 'Descartes veut rendre l’homme « comme maître et possesseur de la nature ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Formule du *Discours de la méthode*, 1637 — le « comme » nuance le projet.', 3),
    ('e8e65fa3-efef-5aa9-ae1e-c90f87c78a26'::uuid, 'd3d69ba9-deba-5641-91c1-ec343fa8c741'::uuid, 'Quel impératif Hans Jonas formule-t-il ?', 'mcq', '["Agir pour que les effets soient compatibles avec une vie humaine durable","Agir selon son intérêt","Ne jamais innover","Suivre le progrès technique"]'::jsonb, 0, '*Le Principe responsabilité*, 1979 : il vise les générations futures.', 4),
    ('e584fe45-13e2-555e-b618-dd8c9bdf08b9'::uuid, 'd3d69ba9-deba-5641-91c1-ec343fa8c741'::uuid, 'L’« heuristique de la peur » consiste à donner plus de poids au pronostic pessimiste.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Parce que l’enjeu — l’irréversible — ne se rattrape pas.', 5),
    ('b8ad9f33-4f51-5494-bb5e-c622aca27bde'::uuid, 'd3d69ba9-deba-5641-91c1-ec343fa8c741'::uuid, 'Que désigne le « Gestell » chez Heidegger ?', 'mcq', '["L’arraisonnement : le monde réduit à un fonds disponible","Un outil de mesure","La technique artisanale","Le progrès scientifique"]'::jsonb, 0, 'Le fleuve cesse d’être un fleuve pour devenir une réserve d’énergie.', 6),
    ('6e35801d-f2b6-5d59-a398-8eb0d8e9d90c'::uuid, 'd3d69ba9-deba-5641-91c1-ec343fa8c741'::uuid, 'Le mythe de Prométhée présente la technique comme un don arraché aux dieux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et puni : la technique a un prix, c’est ce que dit le mythe.', 7),
    ('75fde0d8-0c4f-5e91-bd00-d626c9141f73'::uuid, 'd3d69ba9-deba-5641-91c1-ec343fa8c741'::uuid, 'Quelle formule de Bacon accompagne le projet moderne ?', 'mcq', '["« On ne commande à la nature qu’en lui obéissant »","« La nature est un livre »","« Rien ne se perd, rien ne se crée »","« Connais-toi toi-même »"]'::jsonb, 0, 'La maîtrise passe par la connaissance des lois, non par la force.', 8),
    ('85caf620-a7d7-5164-99b5-d7ecd151ee5a'::uuid, 'fa33ce21-9374-536a-8750-0ace5009a455'::uuid, 'Que désigne l’Anthropocène ?', 'mcq', '["L’activité humaine devenue une force géologique","L’ère des grands singes","La période d’avant l’industrie","Une théorie économique"]'::jsonb, 0, 'Concept popularisé par Crutzen vers 2000.', 1),
    ('711fd291-e8e0-5acc-9f81-332b50c940d7'::uuid, 'fa33ce21-9374-536a-8750-0ace5009a455'::uuid, 'L’Anthropocène remet en cause la séparation entre histoire humaine et histoire naturelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est sa conséquence philosophique la plus lourde.', 2),
    ('c2200859-8e01-5ebd-8a4f-78b34da8a31b'::uuid, 'fa33ce21-9374-536a-8750-0ace5009a455'::uuid, 'Que montre Philippe Descola dans « Par-delà nature et culture » ?', 'mcq', '["Le partage nature/culture est une singularité occidentale","La nature est une invention récente","Les cultures sont toutes identiques","La nature n’existe pas"]'::jsonb, 0, 'D’autres sociétés découpent le monde autrement.', 3),
    ('febd46be-9209-5c19-9596-e20f1d3202b9'::uuid, 'fa33ce21-9374-536a-8750-0ace5009a455'::uuid, 'Sur quel critère Peter Singer étend-il la considération morale ?', 'mcq', '["La sensibilité, la capacité à souffrir","L’intelligence","L’appartenance à une espèce","L’utilité économique"]'::jsonb, 0, 'D’où sa critique du spécisme.', 4),
    ('dbfcbbb5-4a37-574f-8cb9-4a3928d025e0'::uuid, 'fa33ce21-9374-536a-8750-0ace5009a455'::uuid, 'L’écologie profonde d’Arne Næss reconnaît à la nature une valeur intrinsèque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Par opposition à l’écologie superficielle, qui la protège pour notre utilité.', 5),
    ('1ebfce94-7c65-53f7-b42a-f756e7d1c750'::uuid, 'fa33ce21-9374-536a-8750-0ace5009a455'::uuid, 'Que formule Aldo Leopold dans son « éthique de la terre » ?', 'mcq', '["Est juste ce qui préserve l’intégrité de la communauté biotique","La terre appartient à ceux qui la cultivent","La nature doit être laissée intacte partout","L’homme est au sommet du vivant"]'::jsonb, 0, '*Almanach d’un comté des sables*, 1949.', 6),
    ('276b05de-259a-5cb6-a56e-0676da854da2'::uuid, 'fa33ce21-9374-536a-8750-0ace5009a455'::uuid, 'Luc Ferry met en garde contre une écologie qui subordonnerait l’humain à un tout.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Le Nouvel Ordre écologique*, 1992.', 7),
    ('90d42bd8-0b56-556a-ad4b-e5c20c68cb64'::uuid, 'fa33ce21-9374-536a-8750-0ace5009a455'::uuid, 'Selon Bruno Latour, la modernité nous a réellement séparés de la nature.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il soutient l’inverse : nous n’avons jamais été aussi liés qu’en croyant dominer.', 8),
    ('27778df6-58c5-5521-a19a-317f05e23c66'::uuid, '8af701be-0343-5f40-b598-39199b6e5397'::uuid, 'Quel principe le code de Nuremberg pose-t-il en 1947 ?', 'mcq', '["Le consentement volontaire du sujet est essentiel","La gratuité des soins","Le secret médical","La liberté de la recherche"]'::jsonb, 0, 'Il est rédigé après le procès des médecins nazis.', 1),
    ('ceb2d5ec-342d-5ec0-b736-d111d0429945'::uuid, '8af701be-0343-5f40-b598-39199b6e5397'::uuid, 'Quels sont les quatre principes de Beauchamp et Childress ?', 'mcq', '["Autonomie, bienfaisance, non-malfaisance, justice","Liberté, égalité, fraternité, laïcité","Vérité, prudence, courage, tempérance","Utilité, plaisir, sécurité, ordre"]'::jsonb, 0, 'Leur difficulté est qu’ils entrent régulièrement en conflit.', 2),
    ('5a26c697-3646-576e-b080-cd05a075c67c'::uuid, '8af701be-0343-5f40-b598-39199b6e5397'::uuid, 'La loi Claeys-Leonetti de 2016 autorise l’euthanasie active en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle admet la sédation profonde et continue, pas l’euthanasie active.', 3),
    ('3ccf3161-fee8-532f-9a15-261b92ae9003'::uuid, '8af701be-0343-5f40-b598-39199b6e5397'::uuid, 'Qu’est-ce que CRISPR-Cas9 ?', 'mcq', '["Un outil d’édition génétique simple et peu coûteux","Un vaccin","Un test de dépistage","Un logiciel médical"]'::jsonb, 0, 'Disponible depuis 2012, il a rendu l’édition du génome accessible.', 4),
    ('13f2da0f-fdf6-571f-b646-5f6553d44128'::uuid, '8af701be-0343-5f40-b598-39199b6e5397'::uuid, 'La modification des cellules germinales est transmissible aux descendants.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où le moratoire international, franchi en 2018 par He Jiankui.', 5),
    ('84ccecd8-29ac-5bac-b51b-5d8aad3aa7d8'::uuid, '8af701be-0343-5f40-b598-39199b6e5397'::uuid, 'Quel argument kantien est le plus employé en bioéthique ?', 'mcq', '["La personne a une dignité, non un prix","Le bonheur du plus grand nombre","La loi du plus fort","Le contrat social"]'::jsonb, 0, 'Ne jamais traiter l’humanité « simplement comme un moyen ».', 6),
    ('9ab1cefd-7bcd-5531-a95a-2cef4eab0a65'::uuid, '8af701be-0343-5f40-b598-39199b6e5397'::uuid, 'Que reproche Habermas à la programmation génétique d’un enfant ?', 'mcq', '["Elle rompt l’égalité entre les générations","Elle coûte trop cher","Elle est techniquement impossible","Elle est contraire à la religion"]'::jsonb, 0, '*L’Avenir de la nature humaine*, 2001.', 7),
    ('16beea08-ff41-5afd-abd3-005ec2714759'::uuid, '8af701be-0343-5f40-b598-39199b6e5397'::uuid, 'Les questions de bioéthique se tranchent par la science seule.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La science ne dit jamais ce qui doit être : la décision est politique.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('hlp');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('hlp')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 232 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 232 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
